command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: EHRENSCHULDEN (APHASMA)
//
// - sichere GM-Anwendung
// - Zweibeiner und Erwachte
// - zentrale Zweibeiner-Erkennung über Block 2
// - Selbsttarget erlaubt
// - beide Effekte direkt über Block 6
// - Beteiligte gespeichert, kein neues Target
// - Auswahl bis „Fertig“ korrigierbar
// - eine gemeinsame Karte über Block 11
// - roter GM-Button im verborgenen GM-Bereich
// - dieselbe Karte wird nach Verarbeitung aktualisiert
// - Löschen der laufenden Wette öffnet den Schuldnerdialog
// - OHNE Entfernungsprüfung
// ==========================================

(async function () {
    const macroUuid = this?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.Effekt?.CheckTarget ||
        !globalThis.DSK?.Wesen?.IstZweibeiner ||
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.Target?.Merken || !globalThis.DSK?.Target?.Finden ||
        !globalThis.DSK?.Target?.Actor || !globalThis.DSK?.Empfaenger?.GMUndBesitzer ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.Details || !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);

        if (!fwMacro?.execute) {
            return ui.notifications.error(
                "Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!"
            );
        }

        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.Effekt?.CheckTarget ||
        !DSK_FW?.Wesen?.IstZweibeiner ||
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
        !DSK_FW?.Target?.Merken || !DSK_FW?.Target?.Finden ||
        !DSK_FW?.Target?.Actor || !DSK_FW?.Empfaenger?.GMUndBesitzer ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.Details || !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) {
        return ui.notifications.error(
            "Luna sagt 🌙: Das DSK-Framework 01.03 wurde nicht vollständig geladen!"
        );
    }

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Ehrenschulden";
    const vollerName = "Ehrenschulden (Aphasma)";
    const ahne = "Aphasma";

    const laufenderEffektName = "Ehrenschulden: Laufende Wette";
    const schuldEffektName = "Ehrenschulden: Schuld";

    const flagKey = "pendingEhrenschuldenAphasma";
    const technischeDauer = 315360000;
    const symbolPfad = DSK_FW.Symbol(ahne);
    const dauerText = "Bis die Wette beendet wurde";

    const pause = ms =>
        new Promise(resolve =>
            setTimeout(resolve, Math.max(0, Number(ms) || 0))
        );

    const basisBeschreibung =
        `Kann oder will ein Beteiligter eine entstandene Wettschuld nicht begleichen, ` +
        `erhält der Beteiligte Schmerz in Höhe der erzielten QS. Das Fell fällt langsam aus.` +
        `<br><br>Schmerz und Fellverlust bleiben bestehen, bis die Schulden beglichen oder erlassen wurden.` +
        `<br><br><b>Zielkategorie:</b> Zweibeiner und Erwachte`;

    globalThis._dskEhrenschuldenUnterdrueckt ||= new Set();
    globalThis._dskEhrenschuldenDialoge ||= new Set();

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const istAktiverGM = () => {
        const aktiverGM =
            game.users.find(user =>
                user.isGM &&
                user.active
            );

        return aktiverGM
            ? game.user.isGM &&
                game.user.id === aktiverGM.id
            : game.user.isGM;
    };

    const effektSchluessel = effect =>
        effect?.uuid ||
        `${effect?.parent?.uuid || "Actor"}.${effect?.id || "Unbekannt"}`;

    const ladeBeteiligten = async daten => {
        if (!daten) return null;

        const token =
            await DSK_FW.Target.Finden(
                daten
            );

        return token?.actor ||
            await DSK_FW.Target.Actor(
                daten
            );
    };

    const ladeActor = async uuid => {
        if (!uuid) return null;

        try {
            const dokument =
                await fromUuid(uuid);

            return dokument?.documentName === "Token"
                ? dokument.actor
                : dokument || null;
        } catch (error) {
            console.warn(
                "Ehrenschulden: Actor konnte nicht geladen werden.",
                {
                    uuid,
                    error
                }
            );

            return null;
        }
    };

    const findeLaufendenEffekt = (actor, wettId) =>
        actor?.effects?.find(effect =>
            (effect.name || effect.label || "") === laufenderEffektName &&
            effect.getFlag("dsk", "isLaufendeEhrenschuldenWette") === true &&
            effect.getFlag("dsk", "wettId") === wettId
        ) || null;

    const findeSchuldEffekt = (actor, wettId) =>
        actor?.effects?.find(effect =>
            (effect.name || effect.label || "") === schuldEffektName &&
            effect.getFlag("dsk", "isEhrenschuld") === true &&
            effect.getFlag("dsk", "wettId") === wettId
        ) || null;

    const raeumeQSAuf = async actor => {
        if (
            actor?.getFlag(
                "world",
                "letzteGabenQS"
            ) !== undefined
        ) {
            await actor.unsetFlag(
                "world",
                "letzteGabenQS"
            );
        }
    };

    const loescheOhneAusloesung = async effect => {
        if (!effect) return false;

        const schluessel =
            effektSchluessel(effect);

        globalThis._dskEhrenschuldenUnterdrueckt.add(
            schluessel
        );

        try {
            await effect.delete();
            return true;
        } finally {
            setTimeout(
                () =>
                    globalThis._dskEhrenschuldenUnterdrueckt.delete(
                        schluessel
                    ),
                500
            );
        }
    };

    // +++ 4 - ZIELPRÜFUNG +++++++++++++++++++++++++++++++++++++

    const istGueltigerBeteiligter = actor => {
        if (!actor) return false;

        const type =
            String(
                actor.type || ""
            ).toLowerCase();

        const spezies =
            DSK_FW.Wesen._species(
                actor
            );

        if (type === "spirit") {
            return false;
        }

        if (
            [
                "untot",
                "skelett",
                "zombie",
                "leiche",
                "mumie"
            ].some(wort =>
                spezies.includes(wort)
            )
        ) {
            return false;
        }

        return (
            DSK_FW.Wesen.IstZweibeiner(actor) ||
            DSK_FW.Effekt.CheckTarget(actor, "erwachte")
        );
    };

    // +++ 5 - LAUFENDE WETTE DIREKT ÜBER BLOCK 6 ++++++++++++++

    const wendeLaufendeWetteAn = async ({
        casterActor,
        casterName,
        targetActor,
        targetName,
        partnerNamen,
        qs,
        wettId,
        teilnehmer
    }) => {
        if (!casterActor || !targetActor) {
            return false;
        }

        const alteEffekte =
            targetActor.effects.filter(effect =>
                (effect.name || effect.label || "") === laufenderEffektName &&
                effect.getFlag("dsk", "wettId") === wettId
            );

        if (alteEffekte.length) {
            await targetActor.deleteEmbeddedDocuments(
                "ActiveEffect",
                alteEffekte.map(effect => effect.id)
            );
        }

        const erzeugterEffekt =
            await DSK_FW.Effekt.Anwenden({
                name:
                    laufenderEffektName,

                ahne,

                beschreibung:
                    `Dieser Beteiligte hat sich freiwillig auf eine durch Aphasmas Gabe geschützte Wette eingelassen.` +
                    `<br><br><b>Beteiligter:</b> ${targetName}` +
                    `<br><b>Wette mit:</b> ${partnerNamen}` +
                    `<br><b>Gabe gewirkt von:</b> ${casterName}` +
                    `<br><b>Gespeicherte QS:</b> ${qs}` +
                    `<br><br><b>Wirkungsdauer:</b> ${dauerText}`,

                gabeZiel:
                    "",

                qs,

                ziel:
                    targetActor,

                duration: {
                    seconds:
                        technischeDauer,

                    startTime:
                        game.time.worldTime
                },

                flags: {
                    dsk: {
                        isLaufendeEhrenschuldenWette:
                            true,

                        casterUuid:
                            casterActor.uuid,

                        casterName,
                        wettId,
                        qs,

                        beteiligterUuid:
                            targetActor.uuid,

                        beteiligterName:
                            targetName,

                        partnerNamen,

                        teilnehmer:
                            foundry.utils.deepClone(
                                teilnehmer
                            )
                    }
                }
            });

        if (erzeugterEffekt) {
            return Boolean(
                (erzeugterEffekt.name ||
                    erzeugterEffekt.label ||
                    "") === laufenderEffektName &&

                erzeugterEffekt.getFlag(
                    "dsk",
                    "isLaufendeEhrenschuldenWette"
                ) === true &&

                erzeugterEffekt.getFlag(
                    "dsk",
                    "wettId"
                ) === wettId &&

                erzeugterEffekt.getFlag(
                    "dsk",
                    "casterUuid"
                ) === casterActor.uuid
            );
        }

        return Boolean(
            findeLaufendenEffekt(
                targetActor,
                wettId
            )
        );
    };

    // +++ 6 - EHRENSCHULD DIREKT ÜBER BLOCK 6 +++++++++++++++++

    const wendeSchuldAn = async ({
        casterActor,
        casterName,
        targetActor,
        targetName,
        qs,
        wettId
    }) => {
        if (!casterActor || !targetActor) {
            return false;
        }

        const alteEffekte =
            targetActor.effects.filter(effect =>
                (effect.name || effect.label || "") === schuldEffektName &&
                effect.getFlag("dsk", "wettId") === wettId
            );

        if (alteEffekte.length) {
            await targetActor.deleteEmbeddedDocuments(
                "ActiveEffect",
                alteEffekte.map(effect => effect.id)
            );
        }

        const erzeugterEffekt =
            await DSK_FW.Effekt.Anwenden({
                name:
                    schuldEffektName,

                ahne,

                beschreibung:
                    `<b>${targetName}</b> ist den eigenen Schulden erlegen.` +
                    `<br><br>Das Fell von <b>${targetName}</b> fällt langsam aus und ` +
                    `Schmerzen plagen <b>${targetName}</b>, bis die Schulden beglichen wurden.` +
                    `<br><br><b>Schmerz:</b> ${qs} Stufen` +
                    `<br><b>Gabe gewirkt von:</b> ${casterName}` +
                    `<br><b>Wirkungsdauer:</b> Bis die Schulden beglichen oder erlassen wurden`,

                gabeZiel:
                    "",

                qs,

                skills: [
                    "system.status.inpain"
                ],

                key:
                    "direkterSystemwert",

                formel:
                    String(qs),

                ziel:
                    targetActor,

                duration: {
                    seconds:
                        technischeDauer,

                    startTime:
                        game.time.worldTime
                },

                flags: {
                    dsk: {
                        isEhrenschuld:
                            true,

                        casterUuid:
                            casterActor.uuid,

                        casterName,
                        wettId,
                        qs,

                        schuldnerName:
                            targetName
                    }
                }
            });

        if (erzeugterEffekt) {
            const korrekterSystemwert =
                (erzeugterEffekt.changes || [])
                    .some(change =>
                        change.key === "system.status.inpain" &&
                        Number(change.mode) === 2 &&
                        Number(change.value) === qs
                    );

            return Boolean(
                (erzeugterEffekt.name ||
                    erzeugterEffekt.label ||
                    "") === schuldEffektName &&

                erzeugterEffekt.getFlag(
                    "dsk",
                    "isEhrenschuld"
                ) === true &&

                erzeugterEffekt.getFlag(
                    "dsk",
                    "wettId"
                ) === wettId &&

                erzeugterEffekt.getFlag(
                    "dsk",
                    "casterUuid"
                ) === casterActor.uuid &&

                korrekterSystemwert
            );
        }

        return Boolean(
            findeSchuldEffekt(
                targetActor,
                wettId
            )
        );
    };

    // +++ 7 - SONDERNACHRICHTEN +++++++++++++++++++++++++++++++

    const sendeSchuldenAuswertung = ({
        ohneSchuld,
        mitSchuld,
        qs
    }) => {
        const ohneHtml =
            ohneSchuld.length
                ? `<p style="text-align:center;color:#18940F;font-weight:bold;">Ohne Ehrenschuld</p>` +
                    DSK_FW.UI.List(
                        ohneSchuld.map(name =>
                            `<b>${name}</b> – Verpflichtung erfüllt`
                        )
                    )
                : "";

        const mitHtml =
            mitSchuld.length
                ? `${ohneSchuld.length ? "<hr>" : ""}` +
                    `<p style="text-align:center;color:#B30000;font-weight:bold;">Ehrenschuld entstanden</p>` +
                    DSK_FW.UI.List(
                        mitSchuld.map(name =>
                            `<b>${name}</b> – ${qs} Stufen Schmerz`
                        )
                    )
                : "";

        return ChatMessage.create({
            speaker: {
                alias:
                    "System"
            },

            content: `
                ${DSK_FW.UI.Header(
                    "Ehrenschulden – Ausgang der Wette",
                    symbolPfad
                )}

                <div class="dskbox2" style="margin-top:10px;">
                    <p style="text-align:center;margin-top:0;">
                        Die Spielleitung hat den Ausgang der Wette festgelegt.
                    </p>

                    ${ohneHtml}${mitHtml}
                </div>`
        });
    };

    const sendeBeglichenNachricht = name =>
        ChatMessage.create({
            speaker: {
                alias:
                    "System"
            },

            content: `
                ${DSK_FW.UI.Header(
                    "Ehrenschuld beglichen",
                    symbolPfad
                )}

                <div class="dskbox2" style="margin-top:10px;">
                    <p style="margin:0;line-height:1.45;">
                        <b>${name}</b> hat die Schulden beglichen.

                        <br><br>Das Fell kann nachwachsen und die Schmerzen lassen augenblicklich nach.
                    </p>
                </div>`
        });

    // +++ 8 - SCHULDENAUSWAHL +++++++++++++++++++++++++++++++++

    const oeffneSchuldenDialog = async daten => {
        if (
            !daten?.wettId ||
            globalThis._dskEhrenschuldenDialoge.has(
                daten.wettId
            )
        ) {
            return;
        }

        globalThis._dskEhrenschuldenDialoge.add(
            daten.wettId
        );

        const teilnehmer = [];

        for (const eintrag of daten.teilnehmer || []) {
            const actor =
                await ladeBeteiligten(
                    eintrag
                );

            if (actor) {
                teilnehmer.push({
                    ...foundry.utils.deepClone(
                        eintrag
                    ),

                    actor,

                    name:
                        eintrag.name ||
                        DSK_FW.ResolveTokenName(
                            actor
                        )
                });
            }
        }

        if (!teilnehmer.length) {
            globalThis._dskEhrenschuldenDialoge.delete(
                daten.wettId
            );

            return ui.notifications.warn(
                "Luna sagt 🌙: Keine Beteiligten dieser Wette wurden gefunden!"
            );
        }

        const entscheidungen =
            new Map();

        let wirdVerarbeitet = false;
        let wurdeAbgeschlossen = false;

        const zeilenHtml =
            teilnehmer.map((eintrag, index) => `
                <div
                    class="ehrenschuld-zeile"
                    data-index="${index}"
                    style="display:grid;grid-template-columns:minmax(0,1fr) 30px 30px;gap:5px;align-items:center;padding:6px;margin:4px 0;background:rgba(0,0,0,.035);border:1px solid #c9bca6;border-radius:4px;"
                >
                    <div style="min-width:0;">
                        <b>${eintrag.name}</b>

                        <div
                            class="ehrenschuld-status"
                            style="font-size:.78em;color:#666;"
                        >
                            Noch nicht entschieden
                        </div>
                    </div>

                    <button
                        type="button"
                        class="ehrenschuld-plus"
                        title="Keine Ehrenschuld"
                        style="width:30px;height:28px;padding:0;cursor:pointer;background:linear-gradient(#3f7e38,#285424);color:#fff;border:1px solid #163513;border-radius:4px;font-weight:bold;font-size:17px;"
                    >+</button>

                    <button
                        type="button"
                        class="ehrenschuld-minus"
                        title="Ehrenschuld anwenden"
                        style="width:30px;height:28px;padding:0;cursor:pointer;background:linear-gradient(#9b2929,#681919);color:#fff;border:1px solid #430d0d;border-radius:4px;font-weight:bold;font-size:18px;"
                    >−</button>
                </div>
            `).join("");

        const dialog =
            new Dialog({
                title:
                    "Ehrenschulden – Schuldner bestimmen",

                content: `
                    ${DSK_FW.UI.Header(
                        "Ehrenschulden – Schuldner bestimmen",
                        symbolPfad
                    )}

                    <div class="dskbox2" style="margin-top:10px;">
                        <p style="margin-top:0;">
                            Bestimme für jeden Beteiligten den Ausgang der Wette.
                            Die Auswahl kann bis zum Klick auf <b>Fertig</b> geändert werden.
                        </p>

                        <hr>

                        <div style="display:grid;grid-template-columns:minmax(0,1fr) 30px 30px;gap:5px;padding:0 6px 3px;font-size:.8em;font-weight:bold;color:#555;">
                            <span>Beteiligter</span>
                            <span style="text-align:center;">+</span>
                            <span style="text-align:center;">−</span>
                        </div>

                        <div>${zeilenHtml}</div>

                        <hr>

                        <div style="font-size:.84em;color:#555;">
                            <div>
                                <b style="color:#18940F;">+</b>
                                Keine Schuld oder Verpflichtung erfüllt
                            </div>

                            <div>
                                <b style="color:#B30000;">−</b>
                                Ehrenschuld und ${daten.qs} Stufen Schmerz
                            </div>
                        </div>

                        <p
                            class="ehrenschuld-hinweis"
                            style="display:none;text-align:center;color:#B30000;font-weight:bold;margin-bottom:0;"
                        >
                            Bitte entscheide zuerst für alle Beteiligten.
                        </p>
                    </div>`,

                buttons: {
                    finish: {
                        icon:
                            '<i class="fas fa-check"></i>',

                        label:
                            "Fertig",

                        callback: async html => {
                            if (wirdVerarbeitet) {
                                return false;
                            }

                            const container =
                                html instanceof jQuery
                                    ? html[0]
                                    : html;

                            const hinweis =
                                container?.querySelector(
                                    ".ehrenschuld-hinweis"
                                );

                            const finishButton =
                                container?.querySelector(
                                    ".dialog-button.finish"
                                );

                            if (
                                entscheidungen.size !==
                                teilnehmer.length
                            ) {
                                if (hinweis) {
                                    hinweis.style.display =
                                        "block";
                                }

                                ui.notifications.warn(
                                    "Luna sagt 🌙: Bitte entscheide zuerst für alle Beteiligten!"
                                );

                                return false;
                            }

                            wirdVerarbeitet = true;

                            if (finishButton) {
                                finishButton.disabled =
                                    true;
                            }

                            const ohneSchuld = [];
                            const mitSchuld = [];
                            const fehler = [];

                            for (
                                let index = 0;
                                index < teilnehmer.length;
                                index++
                            ) {
                                const eintrag =
                                    teilnehmer[index];

                                const entscheidung =
                                    entscheidungen.get(
                                        index
                                    );

                                try {
                                    if (
                                        entscheidung ===
                                        "schuld"
                                    ) {
                                        const erfolgreich =
                                            await wendeSchuldAn({
                                                casterActor:
                                                    daten.casterActor,

                                                casterName:
                                                    daten.casterName,

                                                targetActor:
                                                    eintrag.actor,

                                                targetName:
                                                    eintrag.name,

                                                qs:
                                                    Number(daten.qs) || 1,

                                                wettId:
                                                    daten.wettId
                                            });

                                        if (!erfolgreich) {
                                            throw new Error(
                                                "Schuld-Effekt konnte nicht erstellt werden."
                                            );
                                        }

                                        mitSchuld.push(
                                            eintrag.name
                                        );
                                    } else {
                                        ohneSchuld.push(
                                            eintrag.name
                                        );
                                    }

                                    const laufenderEffekt =
                                        findeLaufendenEffekt(
                                            eintrag.actor,
                                            daten.wettId
                                        );

                                    if (laufenderEffekt) {
                                        await loescheOhneAusloesung(
                                            laufenderEffekt
                                        );
                                    }
                                } catch (error) {
                                    console.error(
                                        "Ehrenschulden: Entscheidung konnte nicht verarbeitet werden.",
                                        {
                                            eintrag,
                                            entscheidung,
                                            error
                                        }
                                    );

                                    fehler.push(
                                        eintrag.name
                                    );
                                }
                            }

                            if (fehler.length) {
                                wirdVerarbeitet =
                                    false;

                                if (finishButton) {
                                    finishButton.disabled =
                                        false;
                                }

                                ui.notifications.error(
                                    `Luna sagt 🌙: Die Entscheidung konnte für ${fehler.join(", ")} nicht verarbeitet werden!`
                                );

                                return false;
                            }

                            await sendeSchuldenAuswertung({
                                ohneSchuld,
                                mitSchuld,
                                qs:
                                    Number(daten.qs) || 1
                            });

                            wurdeAbgeschlossen =
                                true;

                            globalThis._dskEhrenschuldenDialoge.delete(
                                daten.wettId
                            );

                            return true;
                        }
                    }
                },

                render: html => {
                    const container =
                        html instanceof jQuery
                            ? html[0]
                            : html;

                    if (!container) return;

                    const setzeEntscheidung = (
                        zeile,
                        index,
                        entscheidung
                    ) => {
                        const plus =
                            zeile.querySelector(
                                ".ehrenschuld-plus"
                            );

                        const minus =
                            zeile.querySelector(
                                ".ehrenschuld-minus"
                            );

                        const status =
                            zeile.querySelector(
                                ".ehrenschuld-status"
                            );

                        const istFrei =
                            entscheidung === "frei";

                        entscheidungen.set(
                            index,
                            entscheidung
                        );

                        plus.style.outline =
                            istFrei
                                ? "3px solid #9fe095"
                                : "none";

                        plus.style.filter =
                            istFrei
                                ? "brightness(1.25)"
                                : "none";

                        minus.style.outline =
                            istFrei
                                ? "none"
                                : "3px solid #ef9292";

                        minus.style.filter =
                            istFrei
                                ? "none"
                                : "brightness(1.25)";

                        status.textContent =
                            istFrei
                                ? "Keine Ehrenschuld"
                                : "Ehrenschuld vorgesehen";

                        status.style.color =
                            istFrei
                                ? "#18940F"
                                : "#B30000";

                        const hinweis =
                            container.querySelector(
                                ".ehrenschuld-hinweis"
                            );

                        if (
                            hinweis &&
                            entscheidungen.size ===
                                teilnehmer.length
                        ) {
                            hinweis.style.display =
                                "none";
                        }
                    };

                    for (
                        const zeile of
                        container.querySelectorAll(
                            ".ehrenschuld-zeile"
                        )
                    ) {
                        const index =
                            Number(
                                zeile.dataset.index
                            );

                        zeile.querySelector(
                            ".ehrenschuld-plus"
                        )?.addEventListener(
                            "click",
                            event => {
                                event.preventDefault();

                                if (!wirdVerarbeitet) {
                                    setzeEntscheidung(
                                        zeile,
                                        index,
                                        "frei"
                                    );
                                }
                            }
                        );

                        zeile.querySelector(
                            ".ehrenschuld-minus"
                        )?.addEventListener(
                            "click",
                            event => {
                                event.preventDefault();

                                if (!wirdVerarbeitet) {
                                    setzeEntscheidung(
                                        zeile,
                                        index,
                                        "schuld"
                                    );
                                }
                            }
                        );
                    }

                    container.querySelectorAll(
                        ".dialog-button"
                    ).forEach(button => {
                        button.style.background =
                            "linear-gradient(#76301b,#582617)";

                        button.style.color =
                            "#f8f6f5";

                        button.style.border =
                            "1px solid #000";

                        button.style.fontWeight =
                            "bold";
                    });
                },

                close: () => {
                    if (!wurdeAbgeschlossen) {
                        globalThis._dskEhrenschuldenDialoge.delete(
                            daten.wettId
                        );
                    }
                }
            }, {
                width:
                    470,

                height:
                    "auto"
            });

        dialog.render(true);
    };

    // +++ 9 - GABENSPEZIFISCHER LÖSCH-HOOK ++++++++++++++++++++

    if (globalThis._dskEhrenschuldenDeleteHook) {
        Hooks.off(
            "preDeleteActiveEffect",
            globalThis._dskEhrenschuldenDeleteHook
        );
    }

    globalThis._dskEhrenschuldenDeleteHook =
        Hooks.on(
            "preDeleteActiveEffect",
            async effect => {
                if (
                    !effect ||
                    !istAktiverGM()
                ) {
                    return;
                }

                const schluessel =
                    effektSchluessel(
                        effect
                    );

                if (
                    globalThis._dskEhrenschuldenUnterdrueckt.has(
                        schluessel
                    )
                ) {
                    return;
                }

                const flags =
                    effect.flags?.dsk || {};

                const actor =
                    effect.parent;

                if (!actor) return;

                if (
                    flags.isLaufendeEhrenschuldenWette ===
                    true
                ) {
                    const casterActor =
                        await ladeActor(
                            flags.casterUuid
                        );

                    await oeffneSchuldenDialog({
                        wettId:
                            flags.wettId,

                        qs:
                            Number(flags.qs) || 1,

                        casterActor,

                        casterName:
                            flags.casterName ||
                            "Unbekannt",

                        teilnehmer:
                            foundry.utils.deepClone(
                                flags.teilnehmer || []
                            )
                    });

                    return;
                }

                if (
                    flags.isEhrenschuld ===
                    true
                ) {
                    await sendeBeglichenNachricht(
                        flags.schuldnerName ||
                        DSK_FW.ResolveTokenName(
                            actor
                        )
                    );
                }
            }
        );

    // +++ 10 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++

    const verarbeiteAnfrage = async (
        casterActor,
        daten
    ) => {
        if (
            !casterActor ||
            !daten ||
            !game.user.isGM
        ) {
            return false;
        }

        if (
            daten.casterUuid &&
            daten.casterUuid !== casterActor.uuid
        ) {
            ui.notifications.warn(
                "Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum wirkenden Akteur."
            );

            return false;
        }

        if (
            daten.sceneId &&
            daten.sceneId !== canvas.scene?.id
        ) {
            ui.notifications.warn(
                `Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`
            );

            return false;
        }

        const qs =
            Math.max(
                1,
                Math.floor(
                    Number(daten.qs) || 1
                )
            );

        const casterName =
            daten.casterName ||
            DSK_FW.ResolveTokenName(
                casterActor
            );

        const teilnehmer =
            foundry.utils.deepClone(
                daten.teilnehmer || []
            );

        const misserfolge =
            foundry.utils.deepClone(
                daten.misserfolge || []
            );

        const erfolge = [];

        for (const zielDaten of teilnehmer) {
            const targetActor =
                await ladeBeteiligten(
                    zielDaten
                );

            if (!targetActor) {
                misserfolge.push({
                    name:
                        zielDaten.name ||
                        "Unbekanntes Ziel",

                    grund:
                        "Zielakteur wurde nicht gefunden"
                });

                continue;
            }

            if (
                !istGueltigerBeteiligter(
                    targetActor
                )
            ) {
                misserfolge.push({
                    name:
                        zielDaten.name ||
                        targetActor.name,

                    grund:
                        "Weder Zweibeiner noch Erwachter"
                });

                continue;
            }

            const partnerNamen =
                teilnehmer
                    .filter(eintrag =>
                        eintrag.actorUuid !==
                        zielDaten.actorUuid
                    )
                    .map(eintrag =>
                        eintrag.name
                    )
                    .join(", ");

            try {
                const erfolgreich =
                    await wendeLaufendeWetteAn({
                        casterActor,
                        casterName,
                        targetActor,

                        targetName:
                            zielDaten.name ||
                            targetActor.name,

                        partnerNamen,
                        qs,

                        wettId:
                            daten.wettId,

                        teilnehmer
                    });

                if (erfolgreich) {
                    erfolge.push({
                        name:
                            `${zielDaten.name || targetActor.name} – Wette mit ${partnerNamen}`,

                        rolle:
                            "Beteiligter"
                    });
                } else {
                    misserfolge.push({
                        name:
                            zielDaten.name ||
                            targetActor.name,

                        grund:
                            "Effekt konnte nicht angelegt werden"
                    });
                }
            } catch (error) {
                console.error(
                    "Ehrenschulden: Effektanlage fehlgeschlagen.",
                    {
                        zielDaten,
                        error
                    }
                );

                misserfolge.push({
                    name:
                        zielDaten.name ||
                        targetActor.name,

                    grund:
                        "Effektanlage fehlgeschlagen"
                });
            }

            await pause(1000);
        }

        const erfolgreich =
            erfolge.length > 0;

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId:
                daten.messageId,

            gabenName:
                vollerName,

            ahne,

            beschreibung:
                daten.beschreibung ||
                basisBeschreibung,

            wirkender:
                casterName,

            ziele:
                erfolge,

            misserfolge,

            dauerText:
                daten.dauerText ||
                dauerText,

            erfolgreich
        });

        if (!erfolgreich) {
            ui.notifications.error(
                "Luna sagt 🌙: Die laufende Wette konnte auf keinen Beteiligten angewendet werden!"
            );

            return true;
        }

        ui.notifications.info(
            `Luna sagt 🌙: Ehrenschulden wurde auf ${erfolge.length} Beteiligte angewendet.`
        );

        return true;
    };

    // +++ 11 - GM-MODUS +++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen =
            DSK_FW.GMAnfrage.Finden(
                flagKey
            );

        if (anfragen.length) {
            for (
                const anfrageActor of
                anfragen
            ) {
                const daten =
                    DSK_FW.GMAnfrage.Lesen(
                        anfrageActor,
                        flagKey
                    );

                if (!daten) continue;

                if (
                    await verarbeiteAnfrage(
                        anfrageActor,
                        daten
                    )
                ) {
                    await DSK_FW.GMAnfrage.Loeschen(
                        anfrageActor,
                        flagKey
                    );
                }
            }

            return;
        }
    }

    // +++ 12 - WIRKENDER UND QS +++++++++++++++++++++++++++++++

    let casterActor =
        canvas.tokens.controlled[0]?.actor ||
        game.user.character ||
        null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables
                .map(token =>
                    token.actor
                )
                .find(actor =>
                    actor?.getFlag(
                        "world",
                        "letzteGabenQS"
                    ) !== undefined
                ) ||

            game.actors.find(actor =>
                actor.getFlag(
                    "world",
                    "letzteGabenQS"
                ) !== undefined
            ) ||

            null;
    }

    if (!casterActor) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!"
        );
    }

    if (
        !game.user.isGM &&
        !casterActor.isOwner
    ) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken =
        DSK_FW.Token.Finde(
            casterActor
        );

    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Der Wirkende braucht einen Token auf der Szene!"
        );
    }

    const casterName =
        DSK_FW.ResolveTokenName(
            casterActor
        );

    const qs =
        DSK_FW.QS.Ermitteln({
            actor:
                casterActor,

            gabenName,

            suchbegriffe: [
                "Ehrenschulden Probe",
                "Ehrenschulden"
            ],

            testDataObj:
                typeof testData !== "undefined"
                    ? testData
                    : null,

            fallback:
                0,

            protokollieren:
                true
        });

    if (qs <= 0) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!"
        );
    }

    // +++ 13 - TARGETS PRÜFEN ++++++++++++++++++++++++++++++++++

    const targets =
        Array.from(
            game.user.targets
        );

    if (!targets.length) {
        await raeumeQSAuf(
            casterActor
        );

        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle mindestens einen freiwilligen Wettpartner per Target aus!"
        );
    }

    const gueltigeZiele = [];
    const misserfolge = [];

    for (const targetToken of targets) {
        const targetActor =
            targetToken?.actor;

        const targetName =
            targetToken?.name ||
            targetActor?.name ||
            "Unbekanntes Target";

        if (!targetActor) {
            misserfolge.push({
                name:
                    targetName,

                grund:
                    "Kein gültiger Akteur"
            });

            continue;
        }

        const istWirkender =
            targetActor.uuid === casterActor.uuid ||
            targetActor.id === casterActor.id;

        if (istWirkender) {
            continue;
        }

        if (
            !istGueltigerBeteiligter(
                targetActor
            )
        ) {
            misserfolge.push({
                name:
                    targetName,

                grund:
                    "Weder Zweibeiner noch Erwachter"
            });

            continue;
        }

        const zielDaten =
            DSK_FW.Target.Merken(
                targetToken
            );

        if (zielDaten) {
            gueltigeZiele.push(
                zielDaten
            );
        } else {
            misserfolge.push({
                name:
                    targetName,

                grund:
                    "Target konnte nicht gespeichert werden"
            });
        }
    }

    // +++ 14 - KEIN GÜLTIGER WETTPARTNER ++++++++++++++++++++++

    if (!gueltigeZiele.length) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName:
                vollerName,

            ahne,

            beschreibung:
                basisBeschreibung,

            wirkender:
                casterName,

            ziele:
                [],

            misserfolge,

            dauerText,

            gmBereich:
                false,

            angewendet:
                true,

            erfolgreich:
                false,

            anfragenderUserId:
                game.user.id
        });

        await raeumeQSAuf(
            casterActor
        );

        return;
    }

    // +++ 15 - WIRKENDEN ALS BETEILIGTEN ERGÄNZEN +++++++++++++

    let casterZiel =
        DSK_FW.Target.Merken(
            casterToken
        );

    if (!casterZiel) {
        casterZiel = {
            actorUuid:
                casterActor.uuid,

            tokenId:
                casterToken.id,

            tokenUuid:
                casterToken.document?.uuid ||
                casterToken.uuid ||
                null,

            name:
                casterName
        };
    }

    const teilnehmer = [
        casterZiel,

        ...gueltigeZiele.filter(ziel =>
            ziel.actorUuid !==
            casterZiel.actorUuid
        )
    ];

    const wettId =
        `ehrenschuld-${Date.now()}-${foundry.utils.randomID()}`;

    // +++ 16 - GEMEINSAME KARTE ÜBER BLOCK 11 +++++++++++++++++

    const gmLink =
        DSK_FW.GabenUI.GMMakroButton(
            macroUuid,
            "Effekt anwenden",
            "Das Makro muss durch die Spielleitung ausgeführt werden."
        );

    const nachricht =
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName:
                vollerName,

            ahne,

            beschreibung:
                basisBeschreibung,

            wirkender:
                casterName,

            ziele:
                teilnehmer.map(ziel => ({
                    name:
                        ziel.name,

                    rolle:
                        "Beteiligter"
                })),

            misserfolge,
            dauerText,
            gmLink,

            gmBereich:
                !game.user.isGM,

            anfragenderUserId:
                game.user.id
        });

    if (!nachricht) {
        await raeumeQSAuf(
            casterActor
        );

        return ui.notifications.error(
            "Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!"
        );
    }

    // +++ 17 - ANFRAGEDATEN ++++++++++++++++++++++++++++++++++++

    const anfrageDaten = {
        casterUuid:
            casterActor.uuid,

        casterName,
        qs,
        wettId,

        teilnehmer,
        misserfolge,

        beschreibung:
            basisBeschreibung,

        dauerText,

        sceneId:
            canvas.scene?.id ||
            null,

        requestedByUserId:
            game.user.id,

        messageId:
            nachricht.id,

        macroUuid
    };

    // +++ 18 - GM DIREKT ODER ANFRAGE SPEICHERN +++++++++++++++

    if (game.user.isGM) {
        await verarbeiteAnfrage(
            casterActor,
            anfrageDaten
        );

        await raeumeQSAuf(
            casterActor
        );

        return;
    }

    await DSK_FW.GMAnfrage.Speichern(
        casterActor,
        flagKey,
        anfrageDaten
    );

    // +++ 19 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(
        casterActor
    );

    ui.notifications.info(
        "Luna sagt 🌙: Ehrenschulden wurde bei der Spielleitung beantragt."
    );

}).call(this);
